{"path": "book_store.py", "content": "from collections import Counter
from functools import lru_cache

PRICE = 800
# Total price in cents for a group of n different books.
GROUP_PRICE = {
    1: PRICE,
    2: int(2 * PRICE * 95 / 100),
    3: int(3 * PRICE * 90 / 100),
    4: int(4 * PRICE * 80 / 100),
    5: int(5 * PRICE * 75 / 100),
}


@lru_cache(maxsize=None)
def _best(counts):
    if not counts:
        return 0
    best = None
    for k in range(1, len(counts) + 1):
        # Taking from the largest piles is always optimal for a group of size k.
        rest = list(counts)
        for i in range(k):
            rest[i] -= 1
        new = tuple(sorted((c for c in rest if c > 0), reverse=True))
        cost = GROUP_PRICE[k] + _best(new)
        if best is None or cost < best:
            best = cost
    return best


def total(basket):
    """Return the lowest price in cents for the basket of book numbers."""
    counts = tuple(sorted(Counter(basket).values(), reverse=True))
    return _best(counts)
